def binary_search(name):
	ceil = len(yuri_names) - 1
	floor = 0
	pivot = 0

	while floor < ceil:
		pivot = math.floor((ceil + floor) / 2)

		if yuri_names[pivot]["Name"] < name:
			floor = pivot + 1
		elif yuri_names[pivot]["Name"] > name:
			ceil = pivot - 1
		else:
			return pivot
		
	return math.floor((ceil + floor) / 2)

REVERSE_PREFIX = "Reverse"
HASH_NUDGED_PREFIX = "Bonus"
REVERSE_HASH_NUDGED_PREFIX = "ReverseBonus"

RETURN_PREFIXES = ["", HASH_NUDGED_PREFIX, REVERSE_HASH_NUDGED_PREFIX, REVERSE_PREFIX]

def tucked_binary_search(name):
	# basically, if the binary search returns either the minimum or maximum value, try to make it something more towards the middle.
	# like tucking a bedsheet under the mattress, i guess. 
	# this should make things more interesting for moves whose names don't fit nicely into the list

	classic_number = binary_search(name)

	reversed_number = binary_search(name[::-1])

	# chess moves tend to clump together, so give them a chance to spread out a bit
	# i call this "hash nudging" because you use these bad hashes of the string to nudge it somewhere else in the array
 
	hash_nudged = sum(map(lambda x: ord(x[1]) * x[0],  enumerate(name, start=1)), classic_number) % len(yuri_names)
	reverse_hash_nudged = sum(map(lambda x: ord(x[1]) * x[0],  enumerate(reversed(name), start=1)), classic_number) % len(yuri_names)

	# I feel like just the classic number on its own leads to similar problems as the Lowercase Zone where, say, one player moves the same knight around all the time
	# getting rid of it (and always using hash nudging) does mean there's basically never a tiebreaker needed, but I think the tiebreaker might actually help.
	#if classic_number != lowercase_zone and classic_number > 0 and classic_number < len(yuri_names) - 1: 
		#return (classic_number, hash_nudged)

	# why not just return all three numbers and let the engine part sort it out

	return [classic_number, hash_nudged, reverse_hash_nudged, reversed_number]

stdev = 0.6
firstchunk = stdev*math.sqrt(2*math.pi)
def normal_distribution(x, mean):
	echunk = math.exp(-0.5 * math.pow((x-mean)/stdev,2))
	return (echunk/firstchunk) * 200; # make it a big boy

def calculate_yuri(str_to_calc):

	runningweights = [0,0,0,0]

	yuri_matrix = {
		"Gayness" : [0, 0, 0, 0],
		"Boldness" : [0, 0, 0, 0],
		"Commitment" : [0, 0, 0, 0],
		"Lewdness" : [0, 0, 0, 0],
	}

	# compute every mean for tiebreakers later
	all_four_means = tucked_binary_search(str_to_calc)

	for i, yuri_obj in enumerate(yuri_names):
		quadruple_nameweight = list(map(lambda mean: normal_distribution(i, mean), all_four_means))

		#print("info string Weights: " + repr(triple_nameweight))

		for i in range(len(runningweights)):
			runningweights[i] += quadruple_nameweight[i]
			yuri_matrix["Gayness"][i] += yuri_obj["Gayness"] * quadruple_nameweight[i]
			yuri_matrix["Boldness"][i] += yuri_obj["Boldness"] * quadruple_nameweight[i]
			yuri_matrix["Commitment"][i] += yuri_obj["Commitment"] * quadruple_nameweight[i]
			yuri_matrix["Lewdness"][i] += yuri_obj["Lewdness"] * quadruple_nameweight[i]

	to_return = {
		"Name": str_to_calc
	}

	for k, v in yuri_matrix.items():
		for i, val in enumerate(v):
			to_return[RETURN_PREFIXES[i] + k] = val / runningweights[i]
	
	for i, prefix in enumerate(RETURN_PREFIXES):
		to_return[prefix + "Sum"] = sum(map(lambda x: x[i], yuri_matrix.values())) / runningweights[i]

	return to_return


